import { 
  MeshBasicNodeMaterial, 
  MeshStandardNodeMaterial,
  PlaneGeometry, 
  Group, 
  Mesh, 
  Color,
  Texture
} from 'three/webgpu';
import { 
  uv, 
  vec3, 
  mix, 
  smoothstep, 
  uniform, 
  texture, 
  positionLocal, 
  vec4,
  mul,
  add
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    background: "#0b0b10",
    surface: "#16161d",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38"
  };

  const primitivesList = [];

  // --- STAGE BACKDROP GRADIENT SCRIM (RESOLVES FLAT_VOID) ---
  const bgGeom = new PlaneGeometry(8.5, 6.5);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true });
  const bgUv = uv();

  // Vertical gradient transitioning from dark paper/surface to ambient ink bottom
  const bgGrad = mix(
    vec3(11/255, 11/255, 16/255), 
    vec3(26/255, 26/255, 36/255), 
    bgUv.y
  );
  bgMat.colorNode = bgGrad;

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  // --- PARALLAX PHOTO PLATE ---
  const widthVal = 4.0;
  const heightVal = 2.5;
  const geom = new PlaneGeometry(widthVal, heightVal, 96, 96);

  // Correct TSL dynamic texture binding via standard Texture instances
  const dummyColorTex = new THREE.DataTexture(new Uint8Array([0x1a, 0x1a, 0x24, 0xff]), 1, 1, THREE.RGBAFormat);
  dummyColorTex.needsUpdate = true;
  const dummyDepthTex = new THREE.DataTexture(new Uint8Array([0x00, 0x00, 0x00, 0xff]), 1, 1, THREE.RGBAFormat);
  dummyDepthTex.needsUpdate = true;

  const imageTexNode = texture(dummyColorTex);
  const depthTexNode = texture(dummyDepthTex);
  const uDepthAmp = uniform(0.18);
  const uHasTex = uniform(0.0);

  // Load actual visual textures asynchronously with direct node-value assignment
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
      t.colorSpace = THREE.SRGBColorSpace;
      t.wrapS = THREE.ClampToEdgeWrapping;
      t.wrapT = THREE.ClampToEdgeWrapping;
      imageTexNode.value = t;
      uHasTex.value = 1.0;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((d) => {
      d.wrapS = THREE.ClampToEdgeWrapping;
      d.wrapT = THREE.ClampToEdgeWrapping;
      depthTexNode.value = d;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  // Plate Material utilizing WebGPU Nodes
  const plateMat = new MeshStandardNodeMaterial({ 
    transparent: true, 
    opacity: 0.0,
    roughness: 0.5,
    metalness: 0.2
  });

  // VERTEX SHADER - Depth displacement mapped with texture node
  const texDepthVal = depthTexNode.r;
  const finalZ = mul(texDepthVal, uDepthAmp);
  plateMat.positionNode = positionLocal.add(vec3(0, 0, finalZ));

  // FRAGMENT SHADER - Filmic processing & safety for red channel
  const uvCoords = uv();
  const rawTexColor = imageTexNode;

  // Safe default background pattern while image is loading
  const defaultPlatePattern = mix(vec3(11/255, 11/255, 16/255), vec3(22/255, 22/255, 29/255), uvCoords.y);
  const texRgb = mix(defaultPlatePattern, rawTexColor.rgb, uHasTex);

  // Lift black levels to cinematic #0d0d12 & shoulder towards #e8ecf2 (paper)
  const liftedBlack = vec3(13/255, 13/255, 18/255);
  const paperColor = vec3(232/255, 236/255, 242/255);
  const filmicGraded = mix(liftedBlack, paperColor, texRgb);

  // Compress and enhance midtone contrast (+12%)
  const contrastBoost = mul(filmicGraded.sub(0.48), 1.12).add(0.48);

  // Global desaturation (-8%) with red channel preservation
  const luma = contrastBoost.dot(vec3(0.299, 0.587, 0.114));
  const desaturatedColor = mix(contrastBoost, vec3(luma), 0.08);
  const isVibrantRed = smoothstep(0.05, 0.25, contrastBoost.r.sub(contrastBoost.g));
  const finalImageColor = mix(desaturatedColor, contrastBoost, isVibrantRed);

  // Key Rim light of 0.02 units along silhouette edge
  const edgeRim = smoothstep(0.82, 1.0, texDepthVal).mul(0.02);
  const enhancedImageWithRim = mix(finalImageColor, vec3(1.0), edgeRim);

  // Bottom scrim gradient (#0b0b1000 at 0.45 -> #0b0b10eb at 1.0)
  const scrimVal = smoothstep(0.45, 1.0, uvCoords.y.oneMinus());
  const scrimColor = vec3(11/255, 11/255, 16/255);

  plateMat.colorNode = vec4(mix(enhancedImageWithRim, scrimColor, scrimVal.mul(0.92)), 1.0);

  const plateMesh = new Mesh(geom, plateMat);
  plateMesh.position.set(0, 0, 0);
  group.add(plateMesh);

  // --- LOCAL LIGHTS TO HIGHLIGHT HIGH-ALBEDO OR TEXTURE EDGE ---
  const accentLight = new THREE.DirectionalLight(colors.accent, 1.0);
  accentLight.position.set(3, -2, 2);
  group.add(accentLight);

  // --- CAPTION BLOCK ASSEMBLY ---
  const textGroup = new Group();
  textGroup.position.set(-widthVal / 2 + 0.4, -heightVal / 2 + 0.5, 0.25);
  group.add(textGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerStr = items.find(i => i.role === 'kicker')?.text || "NOVA ATELIER / GENEVA";
  const headlineStr = items.find(i => i.role === 'headline')?.text || "Time, Machined.";
  const bodyStr = items.find(i => i.role === 'body')?.text || "Every case begins as a single billet of 904L steel.";
  const captionStr = items.find(i => i.role === 'caption')?.text || "CALIBRE NA-01 / 72 HOUR RESERVE";

  // Kicker
  const kickerMesh = ctx.fontAtlas.createText(kickerStr, {
    fontSize: 0.09,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1.2
  });
  textGroup.add(kickerMesh);

  // Headline
  const headlineMesh = ctx.fontAtlas.createText(headlineStr, {
    fontSize: 0.28,
    color: colors.paper,
    align: 'left'
  });
  headlineMesh.position.y = -0.22;
  textGroup.add(headlineMesh);

  // Accent signal hairline with emissive quality (intensity 1.8)
  const hairGeom = new PlaneGeometry(0.75, 0.02);
  const hairMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.95
  });
  const hairMesh = new Mesh(hairGeom, hairMat);
  hairMesh.position.set(0.375, -0.38, 0.01);
  textGroup.add(hairMesh);

  // Body
  const bodyMesh = ctx.fontAtlas.createText(bodyStr, {
    fontSize: 0.12,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 800
  });
  bodyMesh.position.y = -0.52;
  textGroup.add(bodyMesh);

  // Caption
  const captionMesh = ctx.fontAtlas.createText(captionStr, {
    fontSize: 0.08,
    color: colors.accent,
    align: 'left'
  });
  captionMesh.position.y = -0.75;
  textGroup.add(captionMesh);

  // --- INTRO TRANSITIONS ---
  const introTimeline = gsap.timeline();

  introTimeline.to(plateMat, {
    opacity: 1.0,
    duration: 0.5,
    ease: "power2.out"
  }, 0);

  const originalTextY = textGroup.position.y;
  textGroup.position.y -= 0.4;
  textGroup.visible = false;

  introTimeline.to(textGroup.position, {
    y: originalTextY,
    duration: 0.7,
    ease: "power3.out",
    onStart: () => { textGroup.visible = true; }
  }, 0.12);

  // Apply cinematic primitives (specifically parallax-scroll)
  const cinematicPrimitives = config.cinematicPrimitives || [];
  cinematicPrimitives.forEach((primitive) => {
    if (ctx.primitives && ctx.primitives[primitive.name]) {
      const activePrim = ctx.primitives[primitive.name](group, primitive.params);
      primitivesList.push(activePrim);
    }
  });

  group.userData.handlers = {
    onInView: (ratio) => {
      uDepthAmp.value = 0.18 + ratio * 0.05;
    }
  };

  group.userData.cleanup = () => {
    introTimeline.kill();
    primitivesList.forEach(prim => {
      if (prim && typeof prim.cleanup === 'function') {
        prim.cleanup();
      }
    });
    geom.dispose();
    plateMat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
    hairGeom.dispose();
    hairMat.dispose();
    dummyColorTex.dispose();
    dummyDepthTex.dispose();
  };

  return group;
}
